(()=>{'use strict';const header=document.querySelector('#sky>header,.portfolio-header');if(!header)return;let last=Math.max(0,scrollY),anchor=last,direction=0,frame=0,idle=0,keyboard=false,touchY=0;function show(){document.body.classList.remove('header-away')}function armIdle(){clearTimeout(idle);idle=setTimeout(()=>{if(!(keyboard&&header.contains(document.activeElement)))document.body.classList.add('header-away')},1000)}function reveal(){show();armIdle()}function update(){frame=0;const y=Math.max(0,scrollY),delta=y-last,next=Math.sign(delta);if(y<80){show();anchor=y}else if(next&&next!==direction){anchor=last}if(y>=80&&Math.abs(y-anchor)>=8){document.body.classList.toggle('header-away',next>0&&!(keyboard&&header.contains(document.activeElement)));anchor=y}if(next)direction=next;last=y;armIdle()}addEventListener('scroll',()=>{if(!frame)frame=requestAnimationFrame(update)},{passive:true});addEventListener('wheel',e=>{if(e.deltaY<0)reveal()},{passive:true});addEventListener('touchstart',e=>{touchY=e.touches[0]?.clientY||0},{passive:true});addEventListener('touchmove',e=>{const y=e.touches[0]?.clientY||0;if(y-touchY>5)reveal();touchY=y},{passive:true});addEventListener('keydown',e=>{if(e.key==='Tab'){keyboard=true;reveal()}});addEventListener('pointerdown',()=>{keyboard=false;armIdle()},{passive:true});header.addEventListener('focusin',reveal);header.addEventListener('focusout',armIdle);header.addEventListener('click',armIdle);addEventListener('pageshow',()=>{last=anchor=Math.max(0,scrollY);direction=0;reveal()});armIdle()})();
